const canvas=$('#canvas'),ctx=canvas.getContext('2d');
const moods=[{name:'Olive afternoon',colors:['#f1eddf','#354b36','#dba24b','#dd6746','#a9b69a']},{name:'Retro sunshine',colors:['#f5bf50','#bf472e','#273e40','#f7efd8','#e48150']},{name:'Blue notes',colors:['#e4edf0','#234d62','#dc693f','#92afba','#f6f1dd']},{name:'Pink pop',colors:['#f4d8dc','#693757','#ed5143','#d4de64','#faf2dd']}];
