function layout(index=0){const m=moods[index%3];state.background=m.colors[0];state.frames=index===1?[frame('text',{x:52,y:65,w:596,h:210,text:'MAKE\nSOME NOISE.',fontSize:86,color:m.colors[1]}),frame('image',{x:65,y:310,w:570,h:455}),frame('text',{x:65,y:810,w:570,h:105,text:'A LITTLE COLOR. A LOT OF YOU.\n2026 — YOUR CREATIVE MOMENT',fontSize:23,color:m.colors[1]})]:[frame('text',{x:64,y:64,w:575,h:50,text:'THE EVERYDAY COLLECTION         VOL. 01',fontSize:17,color:m.colors[1]}),frame('text',{x:60,y:140,w:580,h:220,text:index===2?'Blue\nnotes.':'Slow\nafternoon.',fontSize:100,font:'serif',color:m.colors[1],lineHeight:.98}),frame('image',{x:65,y:395,w:570,h:400,art:true}),frame('text',{x:65,y:835,w:570,h:95,text:'서두르지 않아도 괜찮아.\n나만의 속도로 채우는 오늘의 한 장.',fontSize:21,color:m.colors[1]})];selected=null}
function loadImage(src){if(!src)return null;if(!images.has(src)){const img=new Image();img.onload=render;img.onerror=()=>toast('이미지를 불러올 수 없어요. 다른 파일로 교체해주세요.');img.src=src;images.set(src,img)}return images.get(src)}
function linesFor(c,f){const lines=[];for(const paragraph of f.text.split('\n')){let line='';for(const char of paragraph){if(c.measureText(line+char).width>f.w&&line){lines.push(line);line=char}else line+=char}lines.push(line)}return lines}
function drawArt(c,f){c.save();c.beginPath();c.rect(f.x,f.y,f.w,f.h);c.clip();c.fillStyle='#b8bea3';c.fillRect(f.x,f.y,f.w,f.h);c.fillStyle='#d6c5a2';c.fillRect(f.x,f.y+f.h*.63,f.w,f.h);c.fillStyle='#50624a';c.beginPath();c.ellipse(f.x+f.w*.48,f.y+f.h*.86,f.w*.2,f.h*.1,0,0,Math.PI*2);c.fill();c.fillStyle='#d66d44';c.beginPath();c.roundRect(f.x+f.w*.33,f.y+f.h*.38,f.w*.3,f.h*.46,[8,8,60,60]);c.fill();c.strokeStyle='#38533b';c.lineWidth=7;for(let i=0;i<6;i++){let bx=f.x+f.w*.48,by=f.y+f.h*.42,ex=f.x+f.w*(.19+i*.11),ey=f.y+f.h*(.12+(i%3)*.07);c.beginPath();c.moveTo(bx,by);c.quadraticCurveTo(ex,by*.7+ey*.3,ex,ey);c.stroke();c.fillStyle=i%2?'#e9b95c':'#f0e5b3';c.beginPath();c.ellipse(ex,ey,19,30,i*.5,0,Math.PI*2);c.fill()}c.restore()}
function draw(c,editing=false){c.clearRect(0,0,state.width,state.height);c.fillStyle=state.background;c.fillRect(0,0,state.width,state.height);for(const f of state.frames){if(f.type==='text'){c.save();c.font=`${f.font==='serif'?500:700} ${f.fontSize}px ${f.font==='serif'?'Georgia,serif':'"Noto Sans KR",sans-serif'}`;c.fillStyle=f.color;c.textBaseline='top';c.textAlign=f.align;c.beginPath();c.rect(f.x,f.y,f.w,f.h);c.clip();const lines=linesFor(c,f);lines.forEach((line,i)=>c.fillText(line,f.x+(f.align==='center'?f.w/2:f.align==='right'?f.w:0),f.y+i*f.fontSize*f.lineHeight));c.restore()}else if(f.src){const img=loadImage(f.src);if(img?.complete&&img.naturalWidth){c.save();c.beginPath();c.rect(f.x,f.y,f.w,f.h);c.clip();const ratio=(f.fit==='contain'?Math.min(f.w/img.width,f.h/img.height):Math.max(f.w/img.width,f.h/img.height))*f.zoom;const w=img.width*ratio,h=img.height*ratio;c.drawImage(img,f.x+(f.w-w)/2+f.offsetX,f.y+(f.h-h)/2+f.offsetY,w,h);c.restore()}}else if(f.art){drawArt(c,f)}else if(editing){c.fillStyle='#b5bdab55';c.fillRect(f.x,f.y,f.w,f.h);c.strokeStyle='#819174';c.setLineDash([7,5]);c.strokeRect(f.x,f.y,f.w,f.h);c.setLineDash([]);c.font='22px sans-serif';c.textAlign='center';c.fillStyle='#6a7e60';c.fillText('＋ 사진을 넣어주세요',f.x+f.w/2,f.y+f.h/2);c.textAlign='left'}}
if(editing){const f=state.frames.find(f=>f.id===selected);if(f){c.strokeStyle='#ee653e';c.lineWidth=2;c.strokeRect(f.x,f.y,f.w,f.h);for(const [x,y]of[[f.x,f.y],[f.x+f.w,f.y],[f.x,f.y+f.h],[f.x+f.w,f.y+f.h]]){c.fillStyle='#fff';c.fillRect(x-5,y-5,10,10);c.strokeRect(x-5,y-5,10,10)}}c.strokeStyle='#e5654a';c.lineWidth=1;c.setLineDash([5,4]);for(const g of guides){c.beginPath();if(g.axis==='x'){c.moveTo(g.p,0);c.lineTo(g.p,state.height)}else{c.moveTo(0,g.p);c.lineTo(state.width,g.p)}c.stroke()}c.setLineDash([])}}
function render(){canvas.width=state.width;canvas.height=state.height;canvas.style.aspectRatio=`${state.width}/${state.height}`;draw(ctx,!previewing);$('#paper').value=state.paper;$('#sizeLabel').textContent=`${state.width} × ${state.height} PX · RGB`;$('#undo').disabled=!history.length;$('#redo').disabled=!future.length}
function refresh(){render();inspect();renderLayers()}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function field(label,key,type,value,options=''){return `<label class="field">${label}${type==='textarea'?`<textarea data-prop="${key}">${escapeHTML(value)}</textarea>`:type==='select'?`<select data-prop="${key}">${options}</select>`:`<input data-prop="${key}" type="${type}" value="${escapeHTML(value)}" ${type==='number'?'step="1"':''}>`}</label>`}
function inspect(){const f=state.frames.find(f=>f.id===selected),el=$('#inspector');if(!f){el.innerHTML='<p class="hint">사진이나 글을 클릭하면<br>여기에서 세부 설정을 바꿀 수 있어요.</p>'+field('포스터 배경','background','color',state.background);el.querySelector('input').oninput=e=>{mark();state.background=e.target.value;render()};return}el.innerHTML=(f.type==='text'?field('내용','text','textarea',f.text)+`<div class="row">${field('글꼴','font','select',f.font,'<option value="sans-serif">고딕</option><option value="serif">세리프</option>')}${field('글자 크기','fontSize','number',f.fontSize)}</div><div class="row">${field('글 색상','color','color',f.color)}${field('정렬','align','select',f.align,'<option value="left">왼쪽</option><option value="center">가운데</option><option value="right">오른쪽</option>')}</div>`+field('줄 간격','lineHeight','number',f.lineHeight):'<button id="replaceImage" class="wide">사진 업로드 / 교체</button>'+field('사진 맞춤','fit','select',f.fit,'<option value="cover">프레임 채우기</option><option value="contain">전체 보기</option>')+field('사진 확대 배율','zoom','number',f.zoom)+`<div class="row">${field('사진 좌우','offsetX','number',f.offsetX)}${field('사진 상하','offsetY','number',f.offsetY)}</div>`)+`<div class="row">${field('X','x','number',Math.round(f.x))}${field('Y','y','number',Math.round(f.y))}</div><div class="row">${field('너비','w','number',Math.round(f.w))}${field('높이','h','number',Math.round(f.h))}</div><div class="tools"><button id="duplicate">복제</button><button id="forward">앞으로</button><button id="backward">뒤로</button><button id="remove">삭제</button></div><div id="overflow"></div>`;
el.querySelectorAll('[data-prop]').forEach(input=>{input.value=f[input.dataset.prop];if(['zoom','lineHeight'].includes(input.dataset.prop))input.step='.1';input.onchange=()=>{const key=input.dataset.prop;let val=input.type==='number'?Number(input.value):input.value;if(typeof val==='number'){if(!Number.isFinite(val))return;if(['w','h','fontSize'].includes(key))val=Math.max(10,Math.min(5000,val));if(['zoom','lineHeight'].includes(key))val=Math.max(.1,Math.min(10,val))}mark();f[key]=val;refresh()}});if(f.type==='image')$('#replaceImage').onclick=()=>chooseImage(f);else{ctx.font=`700 ${f.fontSize}px sans-serif`;if(linesFor(ctx,f).length*f.fontSize*f.lineHeight>f.h)$('#overflow').innerHTML='<p class="overflow">글이 프레임을 넘칩니다. 높이나 글자 크기를 조정해주세요.</p>'}$('#duplicate').onclick=()=>{mark();const copy={...clone(f),id:uid(),x:f.x+20,y:f.y+20};state.frames.push(copy);selected=copy.id;refresh()};$('#remove').onclick=removeSelected;$('#forward').onclick=()=>reorder(1);$('#backward').onclick=()=>reorder(-1)}
function reorder(delta){const i=state.frames.findIndex(f=>f.id===selected),j=Math.max(0,Math.min(state.frames.length-1,i+delta));if(i===j)return;mark();const [f]=state.frames.splice(i,1);state.frames.splice(j,0,f);refresh()}
function removeSelected(){if(!selected)return;mark();state.frames=state.frames.filter(f=>f.id!==selected);selected=null;refresh()}
function renderLayers(){$('#layerCount').textContent=state.frames.length+' ITEMS';$('#layers').innerHTML=[...state.frames].reverse().map(f=>`<button class="layer ${selected===f.id?'active':''}" data-id="${f.id}"><b>${f.type==='text'?'T':'▧'}</b><span>${escapeHTML(f.type==='text'?f.text:'사진 프레임')}</span></button>`).join('');$$('.layer').forEach(b=>b.onclick=()=>{selected=b.dataset.id;refresh()})}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*state.width/r.width,y:(e.clientY-r.top)*state.height/r.height}}
canvas.onpointerdown=e=>{const p=point(e);let f=state.frames.find(f=>f.id===selected);const tol=12*state.width/canvas.getBoundingClientRect().width;let corner=f?[[0,0],[1,0],[0,1],[1,1]].find(([a,b])=>Math.abs(p.x-f.x-a*f.w)<tol&&Math.abs(p.y-f.y-b*f.h)<tol):null;if(!corner)f=[...state.frames].reverse().find(f=>p.x>=f.x&&p.x<=f.x+f.w&&p.y>=f.y&&p.y<=f.y+f.h);selected=f?.id||null;if(f){mark();drag={start:p,original:clone(f),corner};canvas.setPointerCapture(e.pointerId)}refresh()};
canvas.onpointermove=e=>{if(!drag)return;const p=point(e),f=state.frames.find(f=>f.id===selected),o=drag.original,dx=p.x-drag.start.x,dy=p.y-drag.start.y;guides=[];if(drag.corner){const [a,b]=drag.corner;f.w=Math.max(25,o.w+(a?dx:-dx));f.h=Math.max(25,o.h+(b?dy:-dy));f.x=a?o.x:o.x+o.w-f.w;f.y=b?o.y:o.y+o.h-f.h}else{f.x=o.x+dx;f.y=o.y+dy;if($('#snap').checked){const tol=6*state.width/canvas.getBoundingClientRect().width;for(const axis of ['x','y']){const len=axis==='x'?'w':'h',end=axis==='x'?state.width:state.height;const targets=[end/2];for(const other of state.frames.filter(v=>v.id!==f.id))targets.push(other[axis],other[axis]+other[len]/2,other[axis]+other[len]);let best={d:tol};for(const offset of [0,f[len]/2,f[len]])for(const target of targets){const d=Math.abs(f[axis]+offset-target);if(d<best.d)best={d,value:target-offset,target}}if(best.value!==undefined){f[axis]=best.value;guides.push({axis,p:best.target})}}}}render()};
