canvas.ondblclick=()=>{const f=state.frames.find(f=>f.id===selected);if(f?.type==='image')chooseImage(f);else $('#inspector textarea')?.focus()};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}});
function undo(){if(!history.length)return;future.push(clone(state));state=history.pop();selected=null;refresh()}function redo(){if(!future.length)return;history.push(clone(state));state=future.pop();selected=null;refresh()}$('#undo').onclick=undo;$('#redo').onclick=redo;
$('#addText').onclick=()=>{mark();const f=frame('text');state.frames.push(f);selected=f.id;refresh()};$('#addImage').onclick=()=>{mark();const f=frame('image');state.frames.push(f);selected=f.id;refresh();chooseImage(f)};
let imageTarget;function chooseImage(f){imageTarget={type:'frame',id:f.id};$('#file').click()}
function readImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('이미지 파일을 선택해주세요.'));const reader=new FileReader();reader.onerror=()=>reject(Error('파일을 읽지 못했어요.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('지원하지 않는 이미지입니다.'));img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,1800/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/png'))};img.src=reader.result};reader.readAsDataURL(file)})}
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const src=await readImage(file);if(imageTarget.type==='frame'){const f=state.frames.find(f=>f.id===imageTarget.id);if(!f)return;mark();f.src=src;f.art=false;loadImage(src);refresh()}else{const colors=await extractColors(src);storage.references.push({id:uid(),name:file.name,category:'내 이미지',src,colors});await persist();renderReferences();toast('이미지와 대표 색상 5개를 저장했어요.')}}catch(err){toast(err.message)}e.target.value=''};
$('#paper').onchange=e=>{const presets={a3:[700,990],a4:[700,990],landscape:[990,700],square:[800,800]};let size=presets[e.target.value];if(!size){const w=prompt('가로 크기 (픽셀, 200~4000)','700');if(w===null){render();return}const h=prompt('세로 크기 (픽셀, 200~4000)','990');if(h===null){render();return}size=[Number(w),Number(h)];if(size.some(v=>!Number.isFinite(v)||v<200||v>4000)){toast('200~4000 사이의 크기를 입력해주세요.');render();return}}mark();const sx=size[0]/state.width,sy=size[1]/state.height;state.frames.forEach(f=>{f.x*=sx;f.w*=sx;f.y*=sy;f.h*=sy});state.width=size[0];state.height=size[1];state.paper=e.target.value;refresh()};
function exportImage(){const c=document.createElement('canvas');c.width=state.width;c.height=state.height;draw(c.getContext('2d'));return c.toDataURL('image/png')}
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click()}
$('#download').onclick=async()=>{await document.fonts.ready;download(exportImage(),'poster-room.png');toast('PNG를 다운로드했어요.')};$('#preview').onclick=()=>{$('#previewDialog img').src=exportImage();$('#previewDialog').showModal()};$('#closePreview').onclick=()=>$('#previewDialog').close();
function applyPalette(colors){mark();state.background=colors[0];state.frames.filter(f=>f.type==='text').forEach((f,i)=>f.color=colors[i===0?1:Math.min(2,colors.length-1)]);refresh();toast('포스터에 팔레트를 적용했어요.')}
function paletteHTML(colors){return colors.map(c=>`<i style="background:${c}" title="${c}"></i>`).join('')}
$('#palettes').innerHTML=moods.map((m,i)=>`<button class="palette" data-mood="${i}" title="${m.name}" aria-label="${m.name} 팔레트 적용">${paletteHTML(m.colors)}</button>`).join('');$$('[data-mood]').forEach(b=>b.onclick=()=>applyPalette(moods[b.dataset.mood].colors));
function renderTemplates(){$('#templates').innerHTML=[0,1,2].map(i=>`<button class="template" data-layout="${i}" title="${['슬로 애프터눈','레트로 타입','블루 노트'][i]}"><i></i><i></i></button>`).join('')+storage.templates.map((t,i)=>`<button class="template" data-saved-template="${i}" title="${escapeHTML(t.name)}"><i></i><i></i></button>`).join('');$$('[data-layout]').forEach(b=>b.onclick=()=>{mark();state.width=700;state.height=990;state.paper='a3';layout(Number(b.dataset.layout));refresh()});$$('[data-saved-template]').forEach(b=>b.onclick=()=>{mark();state=clone(storage.templates[b.dataset.savedTemplate].state);selected=null;refresh()})}
$('#saveTemplate').onclick=async()=>{const name=prompt('템플릿 이름','나의 레이아웃');if(!name?.trim())return;const template=clone(state);template.frames.forEach(f=>{f.text='';f.src=null;f.art=false});storage.templates.push({id:uid(),name:name.trim(),state:template});if(await persist()){renderTemplates();toast('사진과 문구를 비운 템플릿을 저장했어요.')}};
async function openDB(){db=await new Promise((resolve,reject)=>{const req=indexedDB.open('poster-room',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const saved=await new Promise((resolve,reject)=>{const req=db.transaction('data').objectStore('data').get('library');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(saved)storage={...storage,...saved}}
async function persist(){if(!db){toast('브라우저 저장소를 사용할 수 없어요. 백업으로 보관해주세요.');return false}try{await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(clone(storage),'library');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});return true}catch{toast('저장 공간이 부족하거나 저장에 실패했어요. 백업을 내려받아주세요.');return false}}
$('#save').onclick=async()=>{const name=prompt('작업 이름','나의 오후 포스터');if(!name?.trim())return;storage.works.push({id:uid(),name:name.trim(),state:clone(state),thumbnail:exportImage(),date:new Date().toISOString()});if(await persist())toast('작업을 이 브라우저에 저장했어요.')};
function page(name){$$('main').forEach(m=>m.hidden=m.id!==name);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='references')renderReferences();if(name==='library')renderLibrary()}
$$('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();page('editor')};
function renderLibrary(){$('#workGrid').innerHTML=storage.works.length?storage.works.map((w,i)=>`<article class="work"><img src="${w.thumbnail}" alt="${escapeHTML(w.name)}"><h3>${escapeHTML(w.name)}</h3><p>${new Date(w.date).toLocaleDateString('ko-KR')}</p><button data-open="${i}">이어서 편집 ↗</button> <button data-delete="${i}">삭제</button></article>`).join(''):'<p class="empty">아직 저장한 작업이 없어요. 스튜디오에서 첫 포스터를 만들어보세요.</p>';$$('[data-open]').forEach(b=>b.onclick=()=>{mark();state=clone(storage.works[b.dataset.open].state);selected=null;state.frames.forEach(f=>loadImage(f.src));refresh();page('editor')});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('저장한 작업을 삭제할까요?'))return;storage.works.splice(Number(b.dataset.delete),1);await persist();renderLibrary()});$('#savedPalettes').innerHTML=storage.palettes.length?storage.palettes.map((p,i)=>`<article class="work"><h3>${escapeHTML(p.name)}</h3><button class="palette" data-apply-saved="${i}">${paletteHTML(p.colors)}</button></article>`).join(''):'<p class="empty">레퍼런스 화면에서 마음에 드는 팔레트를 저장해보세요.</p>';$$('[data-apply-saved]').forEach(b=>b.onclick=()=>{applyPalette(storage.palettes[b.dataset.applySaved].colors);page('editor')})}
let filter='전체';const refs=[{name:'Slow afternoon',category:'레트로',mood:0},{name:'Make some noise',category:'팝아트',mood:1},{name:'Blue notes',category:'미니멀',mood:2},{name:'Pink state of mind',category:'팝아트',mood:3}];
function graphic(index){const c=document.createElement('canvas');c.width=420;c.height=570;const g=c.getContext('2d'),m=moods[index];g.fillStyle=m.colors[0];g.fillRect(0,0,420,570);g.fillStyle=m.colors[1];g.font='bold 64px Georgia';const text=[['Slow','afternoon.'],['MAKE','SOME','NOISE.'],['Blue','notes.'],['GOOD','THINGS','AHEAD.']][index];text.forEach((t,i)=>g.fillText(t,28,95+i*64));g.fillStyle=m.colors[2];g.beginPath();g.arc(220,390,100,0,Math.PI*2);g.fill();g.fillStyle=m.colors[1];g.fillRect(30,530,360,2);g.font='12px sans-serif';g.fillText('POSTER ROOM   /   ORIGINAL GRAPHIC   /   2026',30,555);return c.toDataURL()}
function renderReferences(){const items=[...refs.map(r=>({...r,src:graphic(r.mood),colors:moods[r.mood].colors})),...storage.references].filter(r=>filter==='전체'||r.category===filter);$('#referenceGrid').innerHTML=items.length?items.map((r,i)=>`<article class="reference"><img src="${r.src}" alt="${escapeHTML(r.name)}"><h3>${escapeHTML(r.name)}</h3><p>${r.category} · ${r.mood!==undefined?'Poster Room 자체 제작 그래픽':'사용자 업로드 · 대표 추출 색상'}</p><button class="palette" data-copy-colors="${i}" title="색상 코드 복사">${paletteHTML(r.colors)}</button><button class="wide" data-use-ref="${i}">이 팔레트로 만들기 ↗</button><button class="wide" data-save-ref="${i}">＋ 팔레트 저장</button></article>`).join(''):'<p class="empty">이미지를 업로드해 나만의 레퍼런스를 모아보세요.</p>';$$('[data-use-ref]').forEach(b=>b.onclick=()=>{applyPalette(items[b.dataset.useRef].colors);page('editor')});$$('[data-save-ref]').forEach(b=>b.onclick=async()=>{const r=items[b.dataset.saveRef];storage.palettes.push({id:uid(),name:r.name,colors:r.colors});if(await persist())toast('팔레트를 내 라이브러리에 저장했어요.')});$$('[data-copy-colors]').forEach(b=>b.onclick=async()=>{const colors=items[b.dataset.copyColors].colors;try{await navigator.clipboard.writeText(colors.join(', '));toast('HEX 색상 코드를 복사했어요.')}catch{prompt('HEX 색상 코드를 복사하세요.',colors.join(', '))}})}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderReferences()});$('#uploadReference').onclick=()=>{imageTarget={type:'reference'};$('#file').click()};
async function extractColors(src){const img=new Image();img.src=src;await img.decode();const c=document.createElement('canvas');c.width=c.height=100;const g=c.getContext('2d');g.drawImage(img,0,0,100,100);const pixels=g.getImageData(0,0,100,100).data,buckets=new Map();for(let i=0;i<pixels.length;i+=4){if(pixels[i+3]<128)continue;const rgb=[pixels[i],pixels[i+1],pixels[i+2]].map(v=>Math.min(255,Math.round(v/32)*32));const key=rgb.map(v=>v.toString(16).padStart(2,'0')).join('');buckets.set(key,(buckets.get(key)||0)+1)}const colors=[...buckets].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k])=>'#'+k);while(colors.length<5)colors.push(colors[0]||'#ffffff');return colors}
$('#backup').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,storage,current:state})],{type:'application/json'}),url=URL.createObjectURL(blob);download(url,'poster-room-backup.json');setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#restore').onclick=()=>$('#backupFile').click();
function validState(s){return s&&Number.isFinite(s.width)&&s.width>=200&&s.width<=4000&&Number.isFinite(s.height)&&s.height>=200&&s.height<=4000&&/^#[0-9a-f]{6}$/i.test(s.background)&&Array.isArray(s.frames)&&s.frames.length<500&&s.frames.every(f=>['text','image'].includes(f.type)&&['x','y','w','h','fontSize','lineHeight','zoom','offsetX','offsetY'].every(k=>Number.isFinite(f[k]))&&f.w>0&&f.h>0&&typeof f.text==='string'&&/^#[0-9a-f]{6}$/i.test(f.color)&&(!f.src||/^data:image\/(png|jpeg|webp);base64,/.test(f.src)))}
$('#backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>80*1024*1024)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!validState(data.current)||!data.storage||!['works','templates','palettes','references'].every(k=>Array.isArray(data.storage[k])))throw Error();if(!data.storage.works.every(w=>validState(w.state)&&/^data:image\/png;base64,/.test(w.thumbnail))||!data.storage.templates.every(t=>validState(t.state))||!data.storage.palettes.every(p=>Array.isArray(p.colors)&&p.colors.every(c=>/^#[0-9a-f]{6}$/i.test(c)))||!data.storage.references.every(r=>/^data:image\/(png|jpeg|webp);base64,/.test(r.src)&&Array.isArray(r.colors)&&r.colors.every(c=>/^#[0-9a-f]{6}$/i.test(c))))throw Error();if(!confirm('현재 라이브러리를 백업 파일의 내용으로 교체할까요?'))return;mark();storage=data.storage;state=data.current;selected=null;await persist();refresh();renderTemplates();page('editor');toast('백업을 복원했어요.')}catch{toast('올바른 Poster Room 백업 파일인지 확인해주세요.')}e.target.value=''};
async function init(){layout();refresh();page('references');try{await openDB()}catch{toast('브라우저 저장소를 열 수 없어요. 백업 기능을 사용해주세요.')}renderTemplates();if(!$('#references').hidden)renderReferences();document.fonts.ready.then(render)}init();
